class BaseProvider:
    """This is a base class for all providers.

    :ivar random: An instance of :class:`mimesis.random.Random`.
    :ivar seed: Seed for random.
    """

    class Meta:
        name: str
        auto_register: bool = True

    def __init_subclass__(cls, **kwargs: t.Any) -> None:
        """Automatically register providers when they are defined.

        This hook is called when a class inherits from BaseProvider.
        It automatically registers the provider in the global registry
        unless auto_register is explicitly set to False in Meta.
        """
        super().__init_subclass__(**kwargs)

        if hasattr(cls, "Meta") and hasattr(cls.Meta, "name"):
            should_register = getattr(cls.Meta, "auto_register", True)
            if should_register:
                ProviderRegistry.register(cls.Meta.name, cls)

    def __init__(
        self,
        *,
        seed: Seed = MissingSeed,
        random: _random.Random | None = None,
    ) -> None:
        """Initialize attributes.

        Keep in mind that locale-independent data providers will work
        only with keyword-only arguments.

        :param seed: Seed for random.
            When set to `None` the current system time is used.
        :param random: Custom random.
            See https://github.com/lk-geimfari/mimesis/issues/1313 for details.
        """
        if random is not None:
            if not isinstance(random, _random.Random):
                raise TypeError("random must be an instance of mimesis.random.Random")
            self.random = random
        else:
            self.random = _random.Random()
        self.seed = seed
        self.reseed(seed)

    def reseed(self, seed: Seed = MissingSeed) -> None:
        """Reseeds the internal random generator.

        In case we use the default seed, we need to create a per instance
        random generator. In this case, two providers with the same seed
        will always return the same values.

        :param seed: Seed for random.
            When set to `None` the current system time is used.
        """
        self.seed = seed
        if seed is MissingSeed:
            # Remove casts after mypy will fix this inference:
            if _random.global_seed is not MissingSeed:
                self.random.seed(t.cast("t.Any", _random.global_seed))
        else:
            self.random.seed(t.cast("t.Any", seed))

    def validate_enum(self, item: t.Any, enum: t.Any) -> t.Any:
        """Validates various enum objects that are used as arguments for methods.

        :param item: Item of an enum object.
        :param enum: Enum object.
        :return: Value of item.
        :raises NonEnumerableError: If the enum does not have such an item.
        """
        if item is None:
            result = self.random.choice_enum_item(enum)
        elif item and isinstance(item, enum):
            result = item
        else:
            raise NonEnumerableError(enum)

        return result.value

    def _read_global_file(self, file_name: str) -> t.Any:
        """Reads a JSON file and returns a dict.

        Reads JSON file from mimesis/data/global/ directory.

        :param file_name: Path to file.
        :raises FileNotFoundError: If the file was not found.
        :return: JSON data.
        """
        with DATADIR.joinpath("global", file_name).open() as f:
            return json.load(f)

    def _has_seed(self) -> bool:
        """Internal API to check if seed is set."""
        return (self.seed is not None and self.seed is not MissingSeed) or (
            _random.global_seed is not None and _random.global_seed is not MissingSeed
        )

    def __str__(self) -> str:
        """Human-readable representation of locale."""
        return self.__class__.__name__

class ProviderRegistry:
    """Central registry for all data providers.

    This registry is automatically populated when provider classes
    are defined via __init_subclass__ hook.
    """

    _providers: t.ClassVar[dict[str, type["BaseProvider"]]] = {}

    @classmethod
    def register(cls, name: str, provider_cls: type["BaseProvider"]) -> None:
        """Register a provider in the global registry.

        :param name: Provider name (from Meta.name)
        :param provider_cls: Provider class
        """
        cls._providers[name] = provider_cls

    @classmethod
    def get_all(cls) -> dict[str, type["BaseProvider"]]:
        """Get all registered providers.

        :return: Dictionary mapping provider names to classes
        """
        return cls._providers.copy()

    @classmethod
    def get(cls, name: str) -> type["BaseProvider"] | None:
        """Get a specific provider by name.

        :param name: Provider name
        :return: Provider class or None
        """
        return cls._providers.get(name)

